import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';
import './AttendancePage.css'; // For custom calendar styles
import moment from 'moment';

const AttendancePage = () => {
  const [allEmployees, setAllEmployees] = useState([]);
  const [allTimeLogs, setAllTimeLogs] = useState([]); // Simulates all logs for the month
  const [isLoading, setIsLoading] = useState(true);

  const [selectedEmployeeId, setSelectedEmployeeId] = useState('All');
  const [selectedDate, setSelectedDate] = useState(new Date());

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const empResponse = await axios.get('http://127.0.0.1:8000/api/employees/');
        const employeesData = empResponse.data.results || empResponse.data || [];
        setAllEmployees(employeesData);
        // Once employees are fetched, generate the full mock log for the month
        if (employeesData.length > 0) {
            setAllTimeLogs(createMockTimeLogs(employeesData));
        }
      } catch (error) {
        console.error("Error fetching data:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, []);

  // Filter logs for the table below based on the calendar's selected date
  const dailyLogs = allTimeLogs.filter(log => 
    moment(log.date).isSame(selectedDate, 'day') &&
    (selectedEmployeeId === 'All' || log.employee.id === parseInt(selectedEmployeeId))
  );

  // This function determines the content/color of each calendar day
  const tileContent = ({ date, view }) => {
    if (view !== 'month') return null;

    if (selectedEmployeeId === 'All') {
      // --- ALL EMPLOYEES VIEW ---
      const logsForDay = allTimeLogs.filter(log => moment(log.date).isSame(date, 'day'));
      const presentCount = logsForDay.filter(l => l.status === 'Present' || l.status === 'Half Day').length;
      if (logsForDay.length === 0) return null;
      return (
        <div className="summary-tile">
          <span className="present-count">{presentCount}</span>
          <span className="total-count">/{logsForDay.length}</span>
        </div>
      );
    } else {
      // --- SINGLE EMPLOYEE VIEW ---
      const logForDay = allTimeLogs.find(log => 
        moment(log.date).isSame(date, 'day') && 
        log.employee.id === parseInt(selectedEmployeeId)
      );
      if (logForDay?.status === 'Present') return <div className="calendar-dot bg-green-500"></div>;
      if (logForDay?.status === 'Absent') return <div className="calendar-dot bg-red-500"></div>;
      if (logForDay?.status === 'Half Day') return <div className="calendar-dot bg-yellow-500"></div>;
      if (logForDay?.status === 'On Leave') return <div className="calendar-dot bg-orange-500"></div>;
    }
    return null;
  };

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-3xl font-bold">Attendance Dashboard</h1>
          <p className="text-sm text-subtext-light">Select an employee and date to view attendance records.</p>
        </div>
        <div className="w-full max-w-xs">
          <label htmlFor="employee-select" className="block text-sm font-medium text-subtext-light mb-1">Filter by Employee</label>
          <select 
            id="employee-select"
            value={selectedEmployeeId}
            onChange={(e) => setSelectedEmployeeId(e.target.value)}
            className="w-full"
          >
            <option value="All">All Employees</option>
            {allEmployees.map(emp => (
              <option key={emp.id} value={emp.id}>{emp.firstName} {emp.lastName}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Main Calendar */}
      <div className="bg-card-light dark:bg-card-dark p-4 rounded-xl shadow-sm">
        <Calendar
          onChange={setSelectedDate}
          value={selectedDate}
          tileContent={tileContent}
          className="w-full border-none"
        />
        <div className="flex justify-center space-x-4 mt-4 text-xs text-gray-600">
          <div className="flex items-center"><span className="legend-dot bg-green-500"></span>Present</div>
          <div className="flex items-center"><span className="legend-dot bg-red-500"></span>Absent</div>
          <div className="flex items-center"><span className="legend-dot bg-yellow-500"></span>Half Day</div>
          <div className="flex items-center"><span className="legend-dot bg-orange-500"></span>On Leave</div>
        </div>
      </div>

      {/* Detailed Log for Selected Day */}
      <div className="mt-8">
        <h3 className="text-xl font-semibold mb-4">
          Detailed Log for {moment(selectedDate).format('MMMM Do, YYYY')}
        </h3>
        <DailyLogTable logs={dailyLogs} isLoading={isLoading} />
      </div>
    </div>
  );
};


// --- HELPER COMPONENTS ---
const DailyLogTable = ({ logs, isLoading }) => { /* ... (same as before) ... */ };
const createMockTimeLogs = (employees) => { /* ... (same as before) ... */ };

export default AttendancePage;
